import{_ as m,C as a,o as g,c as b,j as e,a as o,E as s,a8 as v}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/j4AmIK6OvHc-640.webp",y="/schedule-dashboard/thumbs/yt/j4AmIK6OvHc-1280.webp",r="/schedule-dashboard/thumbs/yt/htod7Nv1cBc-640.webp",f="/schedule-dashboard/thumbs/yt/htod7Nv1cBc-1280.webp",i="/schedule-dashboard/thumbs/yt/s-glGHAa1a4-640.webp",k="/schedule-dashboard/thumbs/yt/s-glGHAa1a4-1280.webp",l="/schedule-dashboard/thumbs/yt/7v2myBde05o-640.webp",_="/schedule-dashboard/thumbs/yt/7v2myBde05o-1280.webp",h="/schedule-dashboard/thumbs/yt/ORVh4GivEU0-640.webp",A="/schedule-dashboard/thumbs/yt/ORVh4GivEU0-1280.webp",c="/schedule-dashboard/thumbs/yt/Zf_e45GiNCE-640.webp",I="/schedule-dashboard/thumbs/yt/Zf_e45GiNCE-1280.webp",p="/schedule-dashboard/thumbs/yt/b9UhZkKjX_A-640.webp",x="/schedule-dashboard/thumbs/yt/b9UhZkKjX_A-1280.webp",d="/schedule-dashboard/thumbs/yt/abw_m-DRi1k-640.webp",G="/schedule-dashboard/thumbs/yt/abw_m-DRi1k-1280.webp",L=JSON.parse('{"title":"AI Digest · Sun 11 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-11","routine":"digest"},"relativePath":"digest/2026-10-11.md","filePath":"digest/[date].md"}'),C={name:"digest/2026-10-11.md"},O=n+" 640w, "+y+" 1280w",S=r+" 640w, "+f+" 1280w",E=i+" 640w, "+k+" 1280w",R=l+" 640w, "+_+" 1280w",B=h+" 640w, "+A+" 1280w",T=c+" 640w, "+I+" 1280w",q=p+" 640w, "+x+" 1280w",H=d+" 640w, "+G+" 1280w",M={id:"ai-digest-·-sun-11-oct-2026",tabindex:"-1"};function j(K,t,N,P,U,V){const w=a("Badge"),u=a("DayFilter");return g(),b("div",null,[e("h1",M,[t[0]||(t[0]=o("AI Digest · Sun 11 Oct 2026 ",-1)),s(w,{type:"tip",text:"8"}),t[1]||(t[1]=o()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#ai-digest-·-sun-11-oct-2026","aria-label":'Permalink to "AI Digest · Sun 11 Oct 2026 <Badge type="tip" text="8" />"'},"​",-1))]),t[3]||(t[3]=e("p",{class:"sub"}," · run date Sun 11 Oct 2026 · 8 videos",-1)),t[4]||(t[4]=e("div",{class:"overview"},[e("p",null,"Eight new AI Engineer talks landed in the last 24 hours. The freshest material is MiniMax's M3 architecture talk and LiveKit's voice-agent benchmark. Three of the eight are AI-gateway pitches (Tailscale, Gravitee, and partly Coder) that cover a lot of the same ground, and the GitHub Copilot and Akamai talks mostly repeat themes you've already seen many times.")],-1)),s(u),t[5]||(t[5]=v('<div class="grid cards2"><article class="it full" id="v-j4AmIK6OvHc" data-title="Latency Is a Budget. Humanlike Is the Goal." data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=j4AmIK6OvHc" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+O+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=j4AmIK6OvHc" target="_blank" rel="noopener">Latency Is a Budget. Humanlike Is the Goal.</a></h3><div class="meta">Jesse Hall, LiveKit · 11 Oct, 7:00 AM IST · 17:01</div><div class="verdict v-worth"><b>Verdict:</b> Worth watching, the best of today&#39;s batch for voice.</div><div class="repeat">🔁 Repeat: &quot;voice agents&quot; — seen 9 times before. 🔁 Repeat: &quot;evals for agents&quot; — seen 11 times before. What&#39;s new here is perceived latency versus measured latency, specific turn-detection numbers, and an open-source end-to-end voice benchmark.</div><div class="sh">Why leaderboards mislead</div><ul><li><strong>Leaderboard trap:</strong> Component leaderboards score speech-to-text, the LLM and text-to-speech separately on clean audio, but you ship a cascade. If speech-to-text hears &quot;Tuesday the 30th&quot; instead of &quot;the 3rd&quot;, the LLM confidently books the wrong day (<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=228s" target="_blank" rel="noopener">3:48</a>–<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=315s" target="_blank" rel="noopener">5:15</a>).</li><li><strong>Measure what callers hear:</strong> Text-to-speech time-to-first-byte looks good on dashboards, but some popular providers send hundreds of milliseconds of silence first, up to about 0.75 s in the worst case. Time-to-first-token is also the wrong LLM metric, because text-to-speech needs a complete first sentence (<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=315s" target="_blank" rel="noopener">5:15</a>–<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=444s" target="_blank" rel="noopener">7:24</a>).</li></ul><div class="sh">Making it feel human</div><ul><li><strong>Async tool calls:</strong> Tools can take 2 to 40+ seconds. One line in a LiveKit tool hands the mic back while the work continues. The hotel-booking demo handles an interruption and a date change mid-call without pausing (<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=444s" target="_blank" rel="noopener">7:24</a>–<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=622s" target="_blank" rel="noopener">10:22</a>).</li><li><strong>Audio-based turn detector:</strong> It listens to rhythm, pitch and intonation. At the same latency budget it cuts users off 4.5% of the time versus 9.9% for the best alternative, and the eval harness is open source (<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=622s" target="_blank" rel="noopener">10:22</a>–<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=667s" target="_blank" rel="noopener">11:07</a>).</li><li><strong>Latency window:</strong> End-of-turn fires from audio, the LLM starts on a provisional transcript, and text-to-speech starts on the first full sentence. Staying under about 1.5 s end to end holds the conversation, and about 600 ms feels human (<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=667s" target="_blank" rel="noopener">11:07</a>–<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=755s" target="_blank" rel="noopener">12:35</a>).</li></ul><div class="sh">Benchmark and model</div><ul><li><strong>Outcome-scored benchmark:</strong> Hundreds of simulated callers interrupt, mumble and change their minds against a real open-source agent. Scoring checks the right booking in the DB, cut-offs, correct names and dates, invented tool calls and PII leaks, and penalizes extra questions or steps. It&#39;s open source, so you can run it on your own agent (evals partly a repeat) (<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=755s" target="_blank" rel="noopener">12:35</a>–<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=886s" target="_blank" rel="noopener">14:46</a>).</li><li><strong>Tuned Gemma 4 31B on LiveKit Inference:</strong> It&#39;s tuned for long prompts, many tools and tight budgets. It passes voice evals 88% of the time and starts speaking in about 380 ms, which he says is over 2x faster than the next model (<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=886s" target="_blank" rel="noopener">14:46</a>–<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=930s" target="_blank" rel="noopener">15:30</a>).</li><li><strong>Checklist:</strong> Set the latency budget first, measure perceived latency, spend the remaining budget on quality, run anything over 1 s asynchronously, and test conversations in production (<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=930s" target="_blank" rel="noopener">15:30</a>–<a href="https://www.youtube.com/watch?v=j4AmIK6OvHc&amp;t=1010s" target="_blank" rel="noopener">16:50</a>).</li></ul></div></article><article class="it full" id="v-htod7Nv1cBc" data-title="How MiniMax M3 Was Built: Sparse Attention and Native Multimodality" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=htod7Nv1cBc" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+S+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=htod7Nv1cBc" target="_blank" rel="noopener">How MiniMax M3 Was Built: Sparse Attention and Native Multimodality</a></h3><div class="meta">Olive Song, MiniMax · 11 Oct, 4:00 AM IST · 15:03</div><div class="verdict v-worth"><b>Verdict:</b> Worth watching if you care about model internals. It&#39;s a dense 15 minutes.</div><p class="note">No heavy repeats. This is model-architecture content, which the channel rarely covers.</p><div class="sh">What M3 is</div><ul><li><strong>Three pillars:</strong> It&#39;s an open-weight model with frontier coding and agent ability, a 1M context window, and native multimodality from step zero. MiniMax Sparse Attention (MSA) gives 9x faster prefill and 15x faster decode than full attention (<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=45s" target="_blank" rel="noopener">0:45</a>–<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=176s" target="_blank" rel="noopener">2:56</a>).</li></ul><div class="sh">MiniMax Sparse Attention (MSA)</div><ul><li><strong>Two branches:</strong> A lightweight index branch (4 query heads, 1 key head, trained with KL loss to match the main branch&#39;s attention scores) picks the high-scoring tokens, and the sparse branch attends only to those (<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=176s" target="_blank" rel="noopener">2:56</a>–<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=262s" target="_blank" rel="noopener">4:22</a>).</li><li><strong>Why not just copy DeepSeek&#39;s DSA:</strong> DSA is tuned for MQA with a big head dimension. Under GQA it makes every KV head attend to the same tokens, which kills diversity, and it turns one contiguous 1×512 read into 4×128 scattered reads. Token-level top-k is also hard to parallelize (<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=262s" target="_blank" rel="noopener">4:22</a>–<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=437s" target="_blank" rel="noopener">7:17</a>).</li><li><strong>Fixes:</strong> Each KV head keeps its own selection, selection moves from token-level to block-level retrieval (fewer candidates, cheaper top-k, more GPU-friendly), and they wrote custom training and inference kernels, with no significant quality drop (<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=437s" target="_blank" rel="noopener">7:17</a>–<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=539s" target="_blank" rel="noopener">8:59</a>).</li></ul><div class="sh">Native multimodality</div><ul><li><strong>Training strategies tried:</strong> Adding vision after pre-training decay (CPT-style) degraded text. Adding it before decay was very sensitive to the data mix and learning rate. Training multimodal from scratch at the same text-token budget barely hurt text (<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=539s" target="_blank" rel="noopener">8:59</a>–<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=669s" target="_blank" rel="noopener">11:09</a>).</li><li><strong>Attention-map evidence:</strong> In CPT-style models, text tokens mostly ignore visual tokens. In native training the attention map looks fused (<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=669s" target="_blank" rel="noopener">11:09</a>–<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=759s" target="_blank" rel="noopener">12:39</a>).</li><li><strong>3D attention in the ViT:</strong> Patches attend across video frames, which also helps image benchmarks. Four frames was the best tradeoff between performance and efficiency (<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=759s" target="_blank" rel="noopener">12:39</a>–<a href="https://www.youtube.com/watch?v=htod7Nv1cBc&amp;t=890s" target="_blank" rel="noopener">14:50</a>).</li></ul></div></article><article class="it full" id="v-s-glGHAa1a4" data-title="An AI Future Without the Lock-In" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=s-glGHAa1a4" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+E+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=s-glGHAa1a4" target="_blank" rel="noopener">An AI Future Without the Lock-In</a></h3><div class="meta">Remy Guercio, Tailscale · 11 Oct, 5:30 AM IST · 19:38</div><div class="verdict v-skim"><b>Verdict:</b> Skim from <a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=473s" target="_blank" rel="noopener">7:53</a> if you want the Tailscale-specific identity angle. Otherwise skip.</div><div class="repeat">🔁 Repeat: &quot;agent observability&quot; — seen 5 times before. It&#39;s an AI-gateway pitch, and one of three gateway talks today.</div><div class="sh">From token maxing to ROI maxing</div><ul><li><strong>Wasted tokens:</strong> In their gateway logs, sessions run hundreds or thousands of messages and tens of millions of tokens without anyone clearing context (<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=127s" target="_blank" rel="noopener">2:07</a>–<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=214s" target="_blank" rel="noopener">3:34</a>).</li><li><strong>Don&#39;t consolidate on one vendor:</strong> Teams panicking over daily Anthropic or Codex bills often lock into one or two vertically integrated toolchains. He argues for keeping choice at four layers: LLMs, data connectors (MCP, CLIs, APIs), interface, and sandbox (<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=214s" target="_blank" rel="noopener">3:34</a>–<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=473s" target="_blank" rel="noopener">7:53</a>).</li></ul><div class="sh">Aperture (Tailscale&#39;s AI gateway)</div><ul><li><strong>Identity without synthetic keys:</strong> It&#39;s built on Tailscale&#39;s WireGuard mesh and the open-source `tsnet` library. Every connection carries machine, tag or user identity plus synced Entra or Okta groups, so there are no per-user API keys. Budgets can be set per model, for example unlimited on a cheap model like GLM 5.2 and narrow on frontier models (<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=559s" target="_blank" rel="noopener">9:19</a>–<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=772s" target="_blank" rel="noopener">12:52</a>).</li><li><strong>MCP gateway plus auth injection:</strong> It wraps plain APIs as MCPs, applies per-team access (marketing gets Calendar and Gmail, engineering gets read-only GitHub), and lets you switch between Cursor, Claude Code and Codex without re-authenticating (<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=772s" target="_blank" rel="noopener">12:52</a>–<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=898s" target="_blank" rel="noopener">14:58</a>).</li><li><strong>Coming soon:</strong> Auth pass-through so identity survives tools like Open WebUI, plus sandbox orchestration in the gateway (<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=941s" target="_blank" rel="noopener">15:41</a>–<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=1067s" target="_blank" rel="noopener">17:47</a>).</li><li><strong>Debugging agents:</strong> Point an agent at its own gateway logs to find out why it spiraled. Users run OpenClaw on their tailnet this way (repeat) (<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=516s" target="_blank" rel="noopener">8:36</a>–<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=559s" target="_blank" rel="noopener">9:19</a>, <a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=1067s" target="_blank" rel="noopener">17:47</a>–<a href="https://www.youtube.com/watch?v=s-glGHAa1a4&amp;t=1154s" target="_blank" rel="noopener">19:14</a>).</li></ul></div></article><article class="it full" id="v-7v2myBde05o" data-title="AI Agents Don&#39;t Read Your Policy Docs. They Hit Your APIs" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=7v2myBde05o" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+R+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=7v2myBde05o" target="_blank" rel="noopener">AI Agents Don&#39;t Read Your Policy Docs. They Hit Your APIs</a></h3><div class="meta">Sam, CTO at Gravitee · 11 Oct, 2:30 AM IST · 17:50</div><div class="verdict v-skim"><b>Verdict:</b> Skim <a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=170s" target="_blank" rel="noopener">2:50</a>–<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=468s" target="_blank" rel="noopener">7:48</a> for the demos. The rest is a product tour.</div><div class="repeat">🔁 Repeat: &quot;MCP servers&quot; — seen 11 times before. 🔁 Repeat: &quot;agent observability&quot; — seen 5 times before. What&#39;s new is a live side-by-side of an agent with prompt-level controls versus one governed by a gateway.</div><div class="sh">Survey framing</div><ul><li><strong>Governance gap:</strong> In Gravitee&#39;s survey, 88% of orgs have an agent in production taking actions, but only 14% have governance around it (<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=43s" target="_blank" rel="noopener">0:43</a>–<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=128s" target="_blank" rel="noopener">2:08</a>).</li></ul><div class="sh">Five live scenarios (Databricks backend, Groq inference)</div><ul><li><strong>Prompt injection:</strong> Asked to also &quot;delete all bookings&quot;, the prompt-controlled agent wiped the table. The gateway-governed agent got a 403 from short-lived JWT token-exchange permissions and still did the allowed part (<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=170s" target="_blank" rel="noopener">2:50</a>–<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=298s" target="_blank" rel="noopener">4:58</a>).</li><li><strong>PII exfiltration:</strong> A request for every guest&#39;s emails and details was returned by the ungoverned agent and blocked at the gateway (<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=298s" target="_blank" rel="noopener">4:58</a>–<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=427s" target="_blank" rel="noopener">7:07</a>).</li><li><strong>Rate and size limits:</strong> A buggy loop sent 8 requests, and the gateway allowed 3 per minute. A 2,000-token transcript prompt was rejected before any LLM call, and off-topic asks like &quot;what&#39;s the weather&quot; are refused (<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=427s" target="_blank" rel="noopener">7:07</a>–<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=468s" target="_blank" rel="noopener">7:48</a>, <a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=638s" target="_blank" rel="noopener">10:38</a>–<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=808s" target="_blank" rel="noopener">13:28</a>).</li><li><strong>Semantic cache:</strong> A built-in Redis cache with a 0-to-1 similarity threshold served repeat asks with about 200 tokens versus about 1,000 (<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=468s" target="_blank" rel="noopener">7:48</a>–<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=638s" target="_blank" rel="noopener">10:38</a>).</li></ul><div class="sh">Other features</div><ul><li><strong>Routing and tool trimming:</strong> Switch Groq, Anthropic, Gemini or OpenAI in &quot;three clicks&quot; with format translation. An &quot;MCP studio&quot; trims a CRM&#39;s 64-tool MCP down to only the needed tools. A new edge feature surfaces shadow-AI traffic from laptops (<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=894s" target="_blank" rel="noopener">14:54</a>–<a href="https://www.youtube.com/watch?v=7v2myBde05o&amp;t=1024s" target="_blank" rel="noopener">17:04</a>).</li></ul></div></article><article class="it full" id="v-ORVh4GivEU0" data-title="Beyond RAG: A Relational Context Engine That Cuts Token Burn" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=ORVh4GivEU0" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+B+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=ORVh4GivEU0" target="_blank" rel="noopener">Beyond RAG: A Relational Context Engine That Cuts Token Burn</a></h3><div class="meta">Peter, Unblocked · 11 Oct, 1:00 AM IST · 19:44</div><div class="verdict v-skim"><b>Verdict:</b> Skim from <a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=479s" target="_blank" rel="noopener">7:59</a> for the natural-language-to-query guardrails, which are practical.</div><div class="repeat">🔁 Repeat: &quot;RAG vs long context&quot; — seen 5 times before. Unblocked also gave a context-engine talk earlier (&quot;How to Generate Mergeable Code with a Context Engine&quot;). What&#39;s new is the structured-query half and the open-source build-along.</div><div class="sh">Context engine payoff</div><ul><li><strong>Cost and time:</strong> The same Claude planning task cost about $1.29 and 1.5 min with the context engine versus about $2.60 and 3 min without, roughly 50% cheaper. The bundle pulled Notion docs, PRs and Slack threads (partly repeat) (<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=133s" target="_blank" rel="noopener">2:13</a>–<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=261s" target="_blank" rel="noopener">4:21</a>).</li><li><strong>Regression found:</strong> Unblocked traced a drop in code-review findings to a switch from Opus 4.6 to 4.8 and opened a fix PR citing the causing PR and the Slack discussion (<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=261s" target="_blank" rel="noopener">4:21</a>–<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=348s" target="_blank" rel="noopener">5:48</a>).</li></ul><div class="sh">Building structured retrieval (open-source &quot;document query engine&quot;)</div><ul><li><strong>Why RAG isn&#39;t enough:</strong> Questions like &quot;PRs I merged last week&quot; or &quot;who reviewed payments most&quot; are queries, not semantic search (<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=390s" target="_blank" rel="noopener">6:30</a>–<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=479s" target="_blank" rel="noopener">7:59</a>).</li><li><strong>Schema discovery:</strong> Sample documents to infer the schema and enums procedurally, without an LLM, and pass the indexes along (<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=619s" target="_blank" rel="noopener">10:19</a>–<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=706s" target="_blank" rel="noopener">11:46</a>).</li><li><strong>Identity resolution:</strong> Fuzzy-match usernames across systems, with an LLM only as tiebreaker (<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=706s" target="_blank" rel="noopener">11:46</a>–<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=793s" target="_blank" rel="noopener">13:13</a>).</li><li><strong>Validation is the key step:</strong> Block dangerous operators like `$function` (raw JS on the DB), hide tenant fields, inject tenant constraints server-side, and reject regex. Feed errors back for self-correction under a max-retry loop, then add full-text search to fix exact-match titles (<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=836s" target="_blank" rel="noopener">13:56</a>–<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=1026s" target="_blank" rel="noopener">17:06</a>).</li><li><strong>Context engine simulator:</strong> An open-source tool that A/B tests a task with and without a context bundle (<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=1115s" target="_blank" rel="noopener">18:35</a>–<a href="https://www.youtube.com/watch?v=ORVh4GivEU0&amp;t=1158s" target="_blank" rel="noopener">19:18</a>).</li></ul></div></article><article class="it full" id="v-Zf_e45GiNCE" data-title="Zero Cold Starts: Serverless AI Agents on Akamai Functions" data-channel="AI Engineer" data-verdict="skip"><a class="th" href="https://www.youtube.com/watch?v=Zf_e45GiNCE" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skip">skip</span><h3><a href="https://www.youtube.com/watch?v=Zf_e45GiNCE" target="_blank" rel="noopener">Zero Cold Starts: Serverless AI Agents on Akamai Functions</a></h3><div class="meta">Thorsten Hans, Akamai · 10 Oct, 11:30 PM IST · 22:37</div><div class="verdict v-skip"><b>Verdict:</b> Skip unless WebAssembly edge hosting interests you.</div><div class="repeat">🔁 Repeat: &quot;MCP servers&quot; — seen 11 times before. The new angle is WebAssembly at the edge.</div><div class="sh">Stack</div><ul><li><strong>Problem:</strong> Region-bound containers and VMs have cold starts of seconds to minutes, and overprovisioning wastes money (<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=45s" target="_blank" rel="noopener">0:45</a>–<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=133s" target="_blank" rel="noopener">2:13</a>).</li><li><strong>Spin + Akamai Functions:</strong> Spin is a CNCF project with a CLI, a Wasmtime-based runtime and SDKs for languages that compile to WASI. Akamai Functions cold-starts per request in under 0.5 ms on average and has a built-in multi-tenant KV store (<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=178s" target="_blank" rel="noopener">2:58</a>–<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=393s" target="_blank" rel="noopener">6:33</a>).</li></ul><div class="sh">Demos</div><ul><li><strong>wasmcp:</strong> Scaffold an MCP server in Rust, TypeScript or Python, compose it with ready-made components (OAuth/OIDC included), run it locally, and test it with MCP Inspector (repeat) (<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=393s" target="_blank" rel="noopener">6:33</a>–<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=660s" target="_blank" rel="noopener">11:00</a>).</li><li><strong>Global deploy:</strong> `spin aka deploy` pushes OCI layers to every region with health checks and is public in about 60 s. A decision-log MCP is used from Zed (<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=744s" target="_blank" rel="noopener">12:24</a>–<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=966s" target="_blank" rel="noopener">16:06</a>).</li><li><strong>Agent on the edge:</strong> A Vercel AI SDK agent calls Ollama on a Linode GPU and does a full loop in about 820–866 ms. JS apps are pre-initialized and memory-snapshotted, which he says beats native JS cold starts, at the cost of a roughly 10 MB StarlingMonkey runtime (<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=966s" target="_blank" rel="noopener">16:06</a>–<a href="https://www.youtube.com/watch?v=Zf_e45GiNCE&amp;t=1228s" target="_blank" rel="noopener">20:28</a>).</li></ul></div></article><article class="it full" id="v-b9UhZkKjX_A" data-title="From Your Laptop to the Pipeline: Scaling Custom Agents with GitHub Copilot" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=b9UhZkKjX_A" target="_blank" rel="noopener"><img src="'+p+'" srcset="'+q+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=b9UhZkKjX_A" target="_blank" rel="noopener">From Your Laptop to the Pipeline: Scaling Custom Agents with GitHub Copilot</a></h3><div class="meta">Jose Palafox, GitHub · 10 Oct, 10:00 PM IST · 19:39</div><div class="verdict v-skim"><b>Verdict:</b> Skip, unless you use Copilot and want the marketplace or `.github-private` details at <a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=424s" target="_blank" rel="noopener">7:04</a>.</div><div class="repeat">🔁 Repeat: &quot;coding agents in production&quot; — seen 9 times before. 🔁 Repeat: &quot;software factory&quot; — seen 6 times before. Little is new beyond Copilot product specifics.</div><ul><li><strong>Architecture:</strong> The IDE, CLI (stream to mobile via `/remote`) and SDK all hit the Copilot API harness, which handles auth, logging, filtering and model routing (<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=86s" target="_blank" rel="noopener">1:26</a>–<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=213s" target="_blank" rel="noopener">3:33</a>).</li><li><strong>Built-in agents:</strong> An Explorer agent runs on Haiku for codebase search, and a &quot;rubber duck&quot; agent has GPT audit an Opus-written plan. Custom agents are scaffolded from a one-line prompt (<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=213s" target="_blank" rel="noopener">3:33</a>–<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=424s" target="_blank" rel="noopener">7:04</a>).</li><li><strong>Sharing:</strong> Marketplaces (a repo plus JSON) give versioned agents, and an org `.github-private` repo pushes agents to everyone. Reuse raises cache hits and lowers cost (<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=424s" target="_blank" rel="noopener">7:04</a>–<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=636s" target="_blank" rel="noopener">10:36</a>).</li><li><strong>Orchestrate:</strong> Turns GitHub issues into sub-agents across repos for cross-service changes (<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=636s" target="_blank" rel="noopener">10:36</a>–<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=723s" target="_blank" rel="noopener">12:03</a>).</li><li><strong>Agentic workflows:</strong> Headless `copilot -p` runs in Actions with slash-command human-in-the-loop gates. The gh-aw project itself has about 200 agents and is built entirely by agents, and GitHub Next &quot;Agentics&quot; has about 30 ready-made ones (repeat) (<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=765s" target="_blank" rel="noopener">12:45</a>–<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=1018s" target="_blank" rel="noopener">16:58</a>).</li><li><strong>Observability:</strong> Moving to CI makes runs OpenTelemetry-instrumented, so you can alert when an agent exceeds its P90 cost (repeat) (<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=1018s" target="_blank" rel="noopener">16:58</a>–<a href="https://www.youtube.com/watch?v=b9UhZkKjX_A&amp;t=1148s" target="_blank" rel="noopener">19:08</a>).</li></ul></div></article><article class="it full" id="v-abw_m-DRi1k" data-title="The Lethal Trifecta Is Already on Your Laptops" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=abw_m-DRi1k" target="_blank" rel="noopener"><img src="'+d+'" srcset="'+H+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=abw_m-DRi1k" target="_blank" rel="noopener">The Lethal Trifecta Is Already on Your Laptops</a></h3><div class="meta">Michael Patterson, Coder · 10 Oct, 8:30 PM IST · 20:44</div><div class="verdict v-skim"><b>Verdict:</b> Skip. Today&#39;s Gravitee talk shows similar controls live.</div><p class="note">Agent security has come up 3 times before, and the lethal trifecta itself came up in an earlier talk. Mostly familiar ground, with no demo.</p><ul><li><strong>The trifecta:</strong> Simon Willison&#39;s term (the transcript says &quot;Ellison&quot;) for private data, internet communication and untrusted downloads. Any two together is unacceptable in an enterprise (<a href="https://www.youtube.com/watch?v=abw_m-DRi1k&amp;t=316s" target="_blank" rel="noopener">5:16</a>–<a href="https://www.youtube.com/watch?v=abw_m-DRi1k&amp;t=403s" target="_blank" rel="noopener">6:43</a>).</li><li><strong>Attack paths:</strong> Prompt injection through error logs, tickets or CI logs, context poisoning, and privilege escalation (<a href="https://www.youtube.com/watch?v=abw_m-DRi1k&amp;t=403s" target="_blank" rel="noopener">6:43</a>–<a href="https://www.youtube.com/watch?v=abw_m-DRi1k&amp;t=491s" target="_blank" rel="noopener">8:11</a>).</li><li><strong>Adoption blockers:</strong> CISO sign-off, DevOps buy-in, alert fatigue, and &quot;shadow AI&quot; (personal subscriptions on work laptops). &quot;Ninja AI&quot; is shadow AI at scale (<a href="https://www.youtube.com/watch?v=abw_m-DRi1k&amp;t=620s" target="_blank" rel="noopener">10:20</a>–<a href="https://www.youtube.com/watch?v=abw_m-DRi1k&amp;t=883s" target="_blank" rel="noopener">14:43</a>).</li><li><strong>Coder&#39;s three controls:</strong> Cloud dev environments for isolation and pre-installed dependencies (which avoids poisoned registries), a model proxy that logs and strips injections or card data, and an agent firewall that blocks commands like `gh repo delete` or dropping a table (sandboxes partly repeat) (<a href="https://www.youtube.com/watch?v=abw_m-DRi1k&amp;t=926s" target="_blank" rel="noopener">15:26</a>–<a href="https://www.youtube.com/watch?v=abw_m-DRi1k&amp;t=1187s" target="_blank" rel="noopener">19:47</a>).</li></ul></div></article></div>',1))])}const Z=m(C,[["render",j]]);export{L as __pageData,Z as default};
